import logging
import sys

if sys.version_info[:2] <= (3, 9):
    import pkg_resources
    entry_points = pkg_resources.iter_entry_points
else:
    import importlib.metadata
    entry_points = importlib.metadata.entry_points

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class FactoryRegistryBase(object):
    _instance = None

    def __init__(self, **kwargs):
        super(FactoryRegistryBase, self).__init__(**kwargs)
        self._map = {}
        for entry_point in entry_points(group=self._group_name):
            logger.debug(f"entry point name: {entry_point.name!r}")
            self._map[entry_point.name] = entry_point.load()
        logger.debug("factory registry: %r", self._map)

    def __getitem__(self, executor_type):
        return self._map[executor_type]


class FileGetterFactoryRegistry(FactoryRegistryBase):
    _group_name = "FileGetterFactory"

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            cls._instance = FileGetterFactoryRegistry()
        return cls._instance


class FilePutterFactoryRegistry(FactoryRegistryBase):
    _group_name = "FilePutterFactory"

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            cls._instance = FilePutterFactoryRegistry()
        return cls._instance

